use chrono::NaiveDate;

#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug)]
pub struct Effectivity { pub from: NaiveDate, pub until: Option<NaiveDate> } // None = open

impl Effectivity {
    pub fn effective_on(&self, as_of: NaiveDate) -> bool {
        as_of >= self.from && self.until.map_or(true, |u| as_of < u)   // [from, until)
    }
}

